parameters.functionCode:
const config = {
  github_token: process.env.GITHUB_API_TOKEN,
  github_repo: process.env.GITHUB_REPO || 'claude-builders-bounty/claude-builders-bounty',
  claude_api_key: process.env.CLAUDE_API_KEY,
  language: process.env.SUMMARY_LANGUAGE || 'EN',
  delivery_method: process.env.DELIVERY_METHOD || 'slack',
  slack_webhook: process.env.SLACK_WEBHOOK,
  discord_webhook: process.env.DISCORD_WEBHOOK,
  email_to: process.env.EMAIL_TO,
  from_email: process.env.FROM_EMAIL || 'noreply@example.com',
  sendgrid_key: process.env.SENDGRID_API_KEY
};

return { config };

const commits = $input.item.json.Get_Commits || [];
const issues = $input.item.json.Get_Issues || [];
const prs = $input.item.json.Get_PRs || [];
const config = $input.item.json.config;

const mergedPRs = prs.filter(pr => pr.merged_at !== null);

const data = {
  week_of: $now.add(-7, 'days').format('YYYY-MM-DD'),
  repo: config.github_repo,
  stats: {
    commits: commits.length,
    issues_closed: issues.length,
    prs_merged: mergedPRs.length
  },
  commits_sample: commits.slice(0, 5).map(c => `- ${c.commit.message.split('\\n')[0]} (by ${c.commit.author.name})`).join('\n'),
  issues_sample: issues.slice(0, 5).map(i => `- ${i.title} (labels: ${i.labels.map(l => l.name).join(', ') || 'none'})`).join('\n'),
  prs_sample: mergedPRs.slice(0, 5).map(pr => `- ${pr.title} (by ${pr.user.login})`).join('\n')
};

return { github_data: data, config };

