{
  "model": "claude-sonnet-4-20250514",
  "max_tokens": 1024,
  "messages": [
    {
      "role": "user",
      "content": "Generate a {{ $json.config.language === 'FR' ? 'French' : 'English' }} narrative summary (3-4 paragraphs) of this GitHub repository's activity. Be conversational and highlight key achievements.

Repository: {{ $json.github_data.repo }}
Period: Week of {{ $json.github_data.week_of }}

Stats:
- Commits: {{ $json.github_data.stats.commits }}
- Issues Closed: {{ $json.github_data.stats.issues_closed }}
- PRs Merged: {{ $json.github_data.stats.prs_merged }}

Sample Commits:
{{ $json.github_data.commits_sample }}

Sample Issues:
{{ $json.github_data.issues_sample }}

Sample PRs:
{{ $json.github_data.prs_sample }}"
    }
  ]
}

{
  "blocks": [
    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": "📊 Weekly Summary: {{ $json.github_data.repo }}",
        "emoji": true
      }
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "{{ $json.body.content[0].text }}"
      }
    },
    {
      "type": "context",
      "elements": [
        {
          "type": "mrkdwn",
          "text": "📈 Stats: *{{ $json.github_data.stats.commits }}* commits • *{{ $json.github_data.stats.issues_closed }}* issues closed • *{{ $json.github_data.stats.prs_merged }}* PRs merged"
        }
      ]
    }
  ]
}

{
  "content": "📊 Weekly GitHub Summary",
  "embeds": [
    {
      "title": "{{ $json.github_data.repo }}",
      "description": "{{ $json.body.content[0].text }}",
      "color": 3447003,
      "fields": [
        {
          "name": "Commits",
          "value": "{{ $json.github_data.stats.commits }}",
          "inline": true
        },
        {
          "name": "Issues Closed",
          "value": "{{ $json.github_data.stats.issues_closed }}",
          "inline": true
        },
        {
          "name": "PRs Merged",
          "value": "{{ $json.github_data.stats.prs_merged }}",
          "inline": true
        }
      ],
      "footer": {
        "text": "Week of {{ $json.github_data.week_of }}"
      }
    }
  ]
}

